customCSS:
.t, .history { color: #585858; }
.join { color: #a1b56c; }
.part, .quit { color: #585858; }
.kick, .error { color: #ab4642; }
.notice { color: #f7ca88; }
.action { color: #ba8baf; }
.mode, .nick, .topic, .server { color: #86c1b9; }
.highlight { color: #d8d8d8; background-color: #383838; border-left: 3px solid #ba8baf; padding-left: 8px; }
.reply { color: #585858; border-left: 2px solid #7cafc2; padding-left: 6px; }
.oper { color: #181818; background-color: #f7ca88; }
.reactions { color: #7cafc2; background-color: #282828; }
.card { background-color: #282828; border-color: #585858; }
.card-title { color: #7cafc2; }
.card-desc { color: #585858; }
.daychange { color: #585858; border-color: #282828; }
